var $bm_rt;
var showCursor = effect('Cursor On/Off')(1);
var blinkSpeed = effect('Cursor Blink Speed')(1);
var animProp = effect('Animation')(1);
var nearestAnimKey = animProp.nearestKey(time);
var prevAnimKeyIndex = Math.max($bm_sub(nearestAnimKey.index, nearestAnimKey.time > time), 1);
var blink = Math.sin($bm_mul($bm_mul(Math.PI, $bm_sub(time, animProp.key(prevAnimKeyIndex).time)), blinkSpeed));
var txtProp = text.sourceText;
var isTyping = time > animProp.key(1).time && txtProp.valueAtTime(time - thisComp.frameDuration * 5) !== txtProp.valueAtTime(time) && time < animProp.key(animProp.numKeys).time;
if (showCursor == 1) {
    if (isTyping) {
        $bm_rt = 100;
    } else {
        $bm_rt = $bm_mul(blink >= 0, 100);
    }
} else {
    $bm_rt = 0;
}
